"""Tjänstekontrakt som har logiska modeller i IG:n: responder-XSD, svarselement och TKB."""
import os

def CFG(X):
    D = lambda r, f: os.path.join(X, r, 'docs', f)
    I = lambda r, f: os.path.join(X, r, 'schemas', 'interactions', f)
    HCD = 'riv.clinicalprocess.healthcond.description'; HCA = 'riv.clinicalprocess.healthcond.actoutcome'
    LOG = 'riv.clinicalprocess.logistics.logistics'; APA = 'riv.clinicalprocess.activityprescription.actoutcome'
    BAS = 'riv.clinicalprocess.healthcond.basic'; CRM = 'riv.crm.requeststatus'; AUD = 'riv.informationsecurity.auditing.log'
    CFG = [
     dict(model='SEEHDSLMDiagnosis', xsd=I(HCD, 'GetDiagnosisInteraction/GetDiagnosisResponder_2.0.xsd'), element='GetDiagnosisResponse', tkb=D(HCD, 'TKB_clinicalprocess_healthcond_description.docx'), contract='GetDiagnosis 2.0'),
     dict(model='SEEHDSLMAlertInformation', xsd=I(HCD, 'GetAlertInformationInteraction/GetAlertInformationResponder_2.0.xsd'), element='GetAlertInformationResponse', tkb=D(HCD, 'TKB_clinicalprocess_healthcond_description.docx'), contract='GetAlertInformation 2.0'),
     dict(model='SEEHDSLMCareDocumentation', xsd=I(HCD, 'GetCareDocumentationInteraction/GetCareDocumentationResponder_3.0.xsd'), element='GetCareDocumentationResponse', tkb=D(HCD, 'TKB_clinicalprocess_healthcond_description.docx'), contract='GetCareDocumentation 3.0'),
     dict(model='SEEHDSLMFunctionalStatus', xsd=I(HCD, 'GetFunctionalStatusInteraction/GetFunctionalStatusResponder_2.0.xsd'), element='GetFunctionalStatusResponse', tkb=D(HCD, 'TKB_clinicalprocess_healthcond_description.docx'), contract='GetFunctionalStatus 2.0'),
     dict(model='SEEHDSLMCareContacts', xsd=I(LOG, 'GetCareContactsInteraction/GetCareContactsResponder_3.0.xsd'), element='GetCareContactsResponse', tkb=D(LOG, 'TKB_clinicalprocess_logistics_logistics.docx'), contract='GetCareContacts 3.0', flatten=['careContactHeader', 'careContactBody']),
     dict(model='SEEHDSLMCarePlans', xsd=I(LOG, 'GetCarePlansInteraction/GetCarePlansResponder_2.0.xsd'), element='GetCarePlansResponse', tkb=D(LOG, 'TKB_clinicalprocess_logistics_logistics.docx'), contract='GetCarePlans 2.0', flatten=['carePlanHeader', 'carePlanBody']),
     dict(model='SEEHDSLMImagingOutcome', xsd=I(HCA, 'GetImagingOutcomeInteraction/GetImagingOutcomeResponder_1.0.xsd'), element='GetImagingOutcomeResponse', tkb=D(HCA, 'TKB_clinicalprocess_healthcond_actoutcome.docx'), contract='GetImagingOutcome 1.0'),
     dict(model='SEEHDSLMLaboratoryOrderOutcome', xsd=I(HCA, 'GetLaboratoryOrderOutcomeInteraction/GetLaboratoryOrderOutcomeResponder_4.2.xsd'), element='GetLaboratoryOrderOutcomeResponse', tkb=D(HCA, 'TKB_clinicalprocess_healthcond_actoutcome.docx'), contract='GetLaboratoryOrderOutcome 4.2'),
     dict(model='SEEHDSLMMaternityMedicalHistory', xsd=I(HCA, 'GetMaternityMedicalHistoryInteraction/GetMaternityMedicalHistoryResponder_2.0.xsd'), element='GetMaternityMedicalHistoryResponse', tkb=D(HCA, 'TKB_clinicalprocess_healthcond_actoutcome.docx'), contract='GetMaternityMedicalHistory 2.0'),
     dict(model='SEEHDSLMReferralOutcome', xsd=I(HCA, 'GetReferralOutcomeInteraction/GetReferralOutcomeResponder_3.2.xsd'), element='GetReferralOutcomeResponse', tkb=D(HCA, 'TKB_clinicalprocess_healthcond_actoutcome.docx'), contract='GetReferralOutcome 3.2'),
     dict(model='SEEHDSLMMedicationHistory', xsd=I(APA, 'GetMedicationHistoryInteraction/GetMedicationHistoryResponder_2.2.xsd'), element='GetMedicationHistoryResponse', tkb=D(APA, 'TKB_clinicalprocess_activityprescription_actoutcome.docx'), contract='GetMedicationHistory 2.2'),
     dict(model='SEEHDSLMVaccinationHistory', xsd=I(APA, 'GetVaccinationHistoryInteraction/GetVaccinationHistoryResponder_2.0.xsd'), element='GetVaccinationHistoryResponse', tkb=D(APA, 'TKB_clinicalprocess_activityprescription_actoutcome.docx'), contract='GetVaccinationHistory 2.0'),
     dict(model='SEEHDSLMObservations', xsd=I(BAS, 'GetObservationsInteraction/GetObservationsResponder_2.0.xsd'), element='GetObservationsResponse', tkb=D(BAS, 'TKB_clinicalprocess_healthcond_basic.docx'), contract='GetObservations 2.0'),
     dict(model='SEEHDSLMRequestActivities', xsd=I(CRM, 'GetRequestActivitiesInteraction/GetRequestActivitiesResponder_2.0.xsd'), element='GetRequestActivitiesResponse', tkb=D(CRM, 'TKB_crm_requeststatus.docx'), contract='GetRequestActivities 2.0'),
     dict(model='SEEHDSLMAccessLog', xsd=I(AUD, 'GetAccessLogsForPatientInteraction/GetAccessLogsForPatientResponder_2.0.xsd'), element='GetAccessLogsForPatientResponse', tkb=D(AUD, 'TKB_informationsecurity_auditing_log.docx'), contract='GetAccessLogsForPatient 2.0'),
    ]
    # Äldre majorversioner som fortfarande används av NPÖ eller 1177 Journal. Domänen klonas från taggen
    # till katalogen <repo>@<tagg>. seed = modellen för senaste versionen, som ger texter där TKB:n saknar dem.
    def OLD(model, repo, tag, xsd, element, tkb, contract, seed, **kw):
        r = f'{repo}@{tag}'
        return dict(model=model, xsd=I(r, xsd), element=element, tkb=D(r, tkb) if tkb else None,
                    contract=contract, seed=seed, tag=tag, **kw)
    CFG += [
     OLD('SEEHDSLMCareDocumentationV2', HCD, '2.1.19', 'GetCareDocumentationInteraction/GetCareDocumentationResponder_2.1.xsd', 'GetCareDocumentationResponse', 'TKB_clinicalprocess_healthcond_description.docx', 'GetCareDocumentation 2.1', 'SEEHDSLMCareDocumentation', page='mapping-getcaredocumentation.md', renames=[('careDocumentation.careDocumentationHeader', 'careDocumentation.header'), ('careDocumentation.careDocumentationBody', 'careDocumentation.body'), ('careDocumentation.careDocumentationBody.clinicalDocumentNote', 'careDocumentation.body'), ('careDocumentation.careDocumentationBody.clinicalDocumentNote.dissentintOpinion', 'careDocumentation.body.dissentingOpinion')]),
     OLD('SEEHDSLMCareContactsV2', LOG, '2.0.7', 'GetCareContactsInteraction/GetCareContactsResponder_2.0.xsd', 'GetCareContactsResponse', 'TKB_clinicalprocess_logistics_logistics.docx', 'GetCareContacts 2.0', 'SEEHDSLMCareContacts', page='mapping-getcarecontacts.md'),
     OLD('SEEHDSLMLaboratoryOrderOutcomeV3', HCA, '3.1.10', 'GetLaboratoryOrderOutcomeInteraction/GetLaboratoryOrderOutcomeResponder_3.1.xsd', 'GetLaboratoryOrderOutcomeResponse', 'TKB_clinicalprocess_healthcond_actoutcome.docx', 'GetLaboratoryOrderOutcome 3.1', 'SEEHDSLMLaboratoryOrderOutcome', renames=[('laboratoryOrderOutcome.laboratoryOrderOutcomeHeader', 'laboratoryOrderOutcome.header'), ('laboratoryOrderOutcome.laboratoryOrderOutcomeBody', 'laboratoryOrderOutcome.body')]),
     OLD('SEEHDSLMVaccinationHistoryV1', APA, '1.0.2', 'GetVaccinationHistoryInteraction/GetVaccinationHistoryResponder_1.0.xsd', 'GetVaccinationHistoryResponse', 'Tjänstekontraktsbeskrivning_riv_clinicalprocess_activityprescription_actoutcome.docx', 'GetVaccinationHistory 1.0', 'SEEHDSLMVaccinationHistory', page='mapping-getvaccinationhistory.md', renames=[(f'vaccinationMedicalRecord.{h}.{p}.orgUnitHSAid', f'vaccinationMedicalRecord.{h}.{p}.orgUnitHSAId') for h, p in [('vaccinationMedicalRecordHeader', 'accountableHealthcareProfessional.healthcareProfessionalOrgUnit'), ('vaccinationMedicalRecordBody', 'registrationRecord.careGiverOrg'), ('vaccinationMedicalRecordBody', 'administrationRecord.prescriberOrg'), ('vaccinationMedicalRecordBody', 'administrationRecord.performerOrg')]] + [('vaccinationMedicalRecord.vaccinationMedicalRecordHeader.legalAuthenticator.legalAuthenticatorHSAid', 'vaccinationMedicalRecord.vaccinationMedicalRecordHeader.legalAuthenticator.legalAuthenticatorHSAId'), ('vaccinationMedicalRecord.vaccinationMedicalRecordBody.administrationRecord.dosage', 'vaccinationMedicalRecord.vaccinationMedicalRecordBody.administrationRecord.dose'), ('vaccinationMedicalRecord.vaccinationMedicalRecordBody.administrationRecord.vaccineType', 'vaccinationMedicalRecord.vaccinationMedicalRecordBody.administrationRecord.typeOfVaccine')]),
     OLD('SEEHDSLMObservationsV1', BAS, '1.2.3', 'GetObservationsInteraction/GetObservationsResponder_1.2.xsd', 'GetObservationsResponse', 'TKB_clinicalprocess_healthcond_basic.docx', 'GetObservations 1.2', 'SEEHDSLMObservations', tkbconv='igs/TKB_clinicalprocess_healthcond_basic/input/fsh/logical-models/GetObservations.fsh', renames=[('observationGroup', 'observations'), ('observationGroup.observation', 'observations.observationBody'), ('observationGroup.patient', 'observations.observationBody.patient'), ('observationGroup.sourceSystem.rivId', 'observations.header.source.systemId'), ('observationGroup.sourceSystem', 'observations.header.source')]),
     OLD('SEEHDSLMRequestActivitiesV1', CRM, '1.0.7', 'GetRequestActivitiesInteraction/GetRequestActivitiesResponder_1.0.xsd', 'GetRequestActivitiesResponse', 'TKB_crm_requeststatus.docx', 'GetRequestActivities 1.0', 'SEEHDSLMRequestActivities', page='mapping-getrequestactivities.md', renames=[('requestActivity.' + a, 'requestActivity.' + b) for a, b in [('senderRequestId', 'body.request.rivId'), ('typeOfRequest', 'body.request.type'), ('requestMedium', 'body.request.medium'), ('requestIssuedByPersonName', 'body.request.author.name'), ('requestIssuedByOrganizationalUnitId', 'body.request.author.organization.rivId'), ('requestIssuedByOrganizationalUnitDescription', 'body.request.author.organization.name'), ('receivingOrganizationalUnitId', 'body.request.receivingOrganization.rivId'), ('receivingOrganizationalUnitDescription', 'body.request.receivingOrganization.name'), ('careUnit', 'header.accessControlHeader.accountableCareUnit'), ('logicalSystemId', 'header.sourceSystemId'), ('statusCode', 'body.statusCode'), ('eventTime', 'body.eventTime')]]),
     OLD('SEEHDSLMAccessLogV1', 'riv.ehr.log', '1.2.4', 'querying/GetAccessLogsForPatientInteraction/GetAccessLogsForPatientResponder_1.1.xsd', 'GetAccessLogsForPatientResponse', 'TKB_ehr_log.docx', 'GetAccessLogsForPatient 1.1 (ehr:log)', 'SEEHDSLMAccessLog', page='mapping-getaccesslogforpatient.md', renames=[('accessLogsResultType', 'accessLogsResult'), ('accessLogsResultType.result', 'accessLogsResult.reportResult'), ('accessLogsResultType.result.resultCode', 'accessLogsResult.reportResult.result.resultCode'), ('accessLogsResultType.result.resultText', 'accessLogsResult.reportResult.result.resultText')]),
    ]
    # Mindre versioner med samma namnrymd som den modellerade versionen. Ingen egen modell; skillnaderna
    # mot senaste minorversionen redovisas på mappningssidan (difftool.py).
    CFG += [
     OLD('SEEHDSLMLaboratoryOrderOutcomeV4_1', HCA, '4.1.3', 'GetLaboratoryOrderOutcomeInteraction/GetLaboratoryOrderOutcomeResponder_4.1.xsd', 'GetLaboratoryOrderOutcomeResponse', 'TKB_clinicalprocess_healthcond_actoutcome.docx', 'GetLaboratoryOrderOutcome 4.1', 'SEEHDSLMLaboratoryOrderOutcome', diffonly=True, page='mapping-getlaboratoryorderoutcome.md'),
     OLD('SEEHDSLMReferralOutcomeV3_1', HCA, '3.1.10', 'GetReferralOutcomeInteraction/GetReferralOutcomeResponder_3.1.xsd', 'GetReferralOutcomeResponse', 'TKB_clinicalprocess_healthcond_actoutcome.docx', 'GetReferralOutcome 3.1', 'SEEHDSLMReferralOutcome', diffonly=True, page='mapping-getreferraloutcome.md'),
    ]
    return CFG
